async function(vars) {
	var dataSource = await model.getDatasource({
		endpoint: "B2B/RemittanceAdviceLine",
		odataAppend: "?$filter=RemittanceAdviceId eq " + vars.paymentId + "&$expand=InvoiceReference($expand=Invoice),CreditReference($expand=Credit)&$orderby=LineNumber asc"
	});
	var lineGrid  = new GridWidget(vars.element, dataSource);
	lineGrid.editable = false;
	lineGrid.sortable = false;
	lineGrid.filterable = false;
	lineGrid.pageable = true;
	lineGrid.scrollable = true;
	lineGrid.groupable = false;
	lineGrid.columns = [
		{ field: "LineNumber", type: "number", title: "[resource_shortdisplayname[LineNumber]]", width: 60 },
		{ field: "Type", title: "[resource_shortdisplayname[Type]]", template: "#=(InvoiceReferenceId != null) ? '[resource_displayname[salesinvoice]]' : '[resource_displayname[creditnote]]' #", width: 80},
		{ field: "Number", title: "[resource_shortdisplayname[Number]]", template: "#=(InvoiceReferenceId != null) ? InvoiceReference.Invoice.Number : CreditReference.Credit.Number #", width: 80},
		{ field: "Description", type: "string", title: "[resource_shortdisplayname[Description]]", width: 100},
		{ field: "LinePrice", type: "number", title: "[resource_shortdisplayname[LinePrice]]", format: "{0:" + type.moneyFormat + "}", width: 70, attributes:{style:"text-align:right;"} },
		{ field: "CurrencyId", type: "string", title: "[resource_shortdisplayname[CurrencyId]]", width: 60 },
		{ field: "LastUpdated", type: "date", title: "[resource_shortdisplayname[LastUpdated]]", format: "{0:" + type.dateFormat + "}", width: 90 }
	];
	lineGrid.commands.push({
		name: "view",
		icon: "k-i-share",
		text: "[resource_displayname[view]]",
		href: "#:Payment.transactionLink(data)#"
});
	vars.LineGrid = lineGrid;
	return lineGrid;
}
